 async function refreshManagedUsers(){
  if(!supabase||!adminUnits.length)return;
  setStaffLoading(true);setStaffError("");
  try {
    const {data:sessionData}=await supabase.auth.getSession();
    if(!sessionData.session?.access_token){setStaffError("Sua sessão expirou. Entre novamente para consultar os usuários.");return}
    const {data,error}=await supabase.functions.invoke("gerenciar-usuarios-comerciais",{body:{action:"list"},headers:{Authorization:"Bearer "+sessionData.session.access_token}});
    if(error||!data?.ok){
      let reason=data?.error||"";
      if(!reason&&error&&"context" in error){try{const payload=await (error as any).context?.json?.();reason=payload?.error||""}catch{}}
      setStaffError(reason||"Não foi possível consultar os usuários. Clique em Atualizar para tentar novamente.");
    } else {
      setManagedUsers((data.users||[]) as ManagedUser[]);
      setStaffError("");
      setStaffMessage("");
    }
  }catch{
    setStaffError("Não foi possível comunicar com o servidor. Verifique a conexão e tente novamente.");
  }finally{setStaffLoading(false)}
 }
