 const incoming=filtered.filter(e=>e.type==="entrada").reduce((s,e)=>s+e.amount,0),outgoing=filtered.filter(e=>e.type==="saida").reduce((s,e)=>s+e.amount,0),balance=incoming-outgoing;
 const ticketsFiltered=tickets.filter(t=>(unit==="todos"||t.estabelecimento_slug===unit)&&(view==="dashboard"?dashboardValid&&(!t.criada_em||(t.criada_em.slice(0,10)>=dashboardRange[0]&&t.criada_em.slice(0,10)<=dashboardRange[1])):(!t.criada_em||t.criada_em.slice(0,10)>=dateStart(period))));
 const visibleTickets=ticketsFiltered.filter(t=>(ticketStatus==="todos"||(ticketStatus==="pendentes"?["recebida","em_analise"].includes(t.status||"recebida"):t.status===ticketStatus))&&(!ticketSearch.trim()||[t.protocolo,t.nome,t.mensagem,t.categoria,unitName(t.estabelecimento_slug)].join(" ").toLocaleLowerCase("pt-BR").includes(ticketSearch.trim().toLocaleLowerCase("pt-BR"))));
 const pending=ticketsFiltered.filter(t=>!t.status||["recebida","em_analise","pendente","novo","aberto"].includes(t.status.toLowerCase())).length;
 const resultByUnit=selectableUnits.map(u=>{const list=filtered.filter(e=>e.unit===u.slug);const inc=list.filter(e=>e.type==="entrada").reduce((s,e)=>s+e.amount,0);const out=list.filter(e=>e.type==="saida").reduce((s,e)=>s+e.amount,0);return {...u,income:inc,expense:out,balance:inc-out}});
 const chartStart=view==="dashboard"?dashboardRange[0]:dateStart(period);
 const chartEnd=view==="dashboard"?dashboardRange[1]:localDay();
 const days:string[]=[];
 if(chartStart&&chartEnd&&chartStart<=chartEnd){const cursor=new Date(chartStart+"T12:00:00"),end=new Date(chartEnd+"T12:00:00");while(cursor<=end&&days.length<3660){days.push([cursor.getFullYear(),String(cursor.getMonth()+1).padStart(2,"0"),String(cursor.getDate()).padStart(2,"0")].join("-"));cursor.setDate(cursor.getDate()+1)}}
 const chartDaily=days.map(day=>{const rows=filtered.filter(e=>e.date===day);return {day,entrada:rows.filter(e=>e.type==="entrada").reduce((n,e)=>n+e.amount,0),saida:rows.filter(e=>e.type==="saida").reduce((n,e)=>n+e.amount,0),supermercado:rows.filter(e=>e.type==="entrada"&&e.unit==="supermercado").reduce((n,e)=>n+e.amount,0),academia:rows.filter(e=>e.type==="entrada"&&e.unit==="academia-camara-fria").reduce((n,e)=>n+e.amount,0),acai:rows.filter(e=>e.type==="entrada"&&e.unit==="acai").reduce((n,e)=>n+e.amount,0)}});
 const groupDays=chartDaily.length>90?30:chartDaily.length>12?7:1;
 const chart=Array.from({length:Math.ceil(chartDaily.length/groupDays)},(_,i)=>{const group=chartDaily.slice(i*groupDays,(i+1)*groupDays);const first=group[0]?.day||"";const last=group[group.length-1]?.day||"";return {day:groupDays===1?fmtDate(first).slice(0,5):fmtDate(first).slice(0,5)+"–"+fmtDate(last).slice(0,5),entrada:group.reduce((n,d)=>n+d.entrada,0),saida:group.reduce((n,d)=>n+d.saida,0),supermercado:group.reduce((n,d)=>n+d.supermercado,0),academia:group.reduce((n,d)=>n+d.academia,0),acai:group.reduce((n,d)=>n+d.acai,0)}});
 const recentEntries=[...filtered].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 const donut=resultByUnit.map(u=>({name:u.name,value:u.income,color:u.color}));
 const totalByCategory=Object.entries(filtered.reduce((acc:Record<string,{in:number;out:number}>,e)=>{const k=e.category||"Não informada";if(!acc[k])acc[k]={in:0,out:0};acc[k][e.type==="entrada"?"in":"out"]+=e.amount;return acc},{})).sort((a,b)=>(b[1].in+b[1].out)-(a[1].in+a[1].out));
 const expenseCategories=totalByCategory.filter(([,v])=>v.out>0).sort((a,b)=>b[1].out-a[1].out).slice(0,6).map(([name,v])=>({name,value:v.out}));
 const noData=<div className="mg-no-data"><BarChart3 size={28}/><strong>Sem dados no período</strong><small>Os gráficos serão preenchidos automaticamente com as movimentações registradas.</small></div>;
