 {reportUnit==="todos"&&<div className="mg-report-section"><h3>Resumo por estabelecimento</h3><div className="mg-report-unit-grid">{reportResultByUnit.map(u=><div className="mg-report-unit-block" key={u.slug}><strong>{u.name}</strong>{reportShowsIn&&<span>Entradas: <b>{money(u.income)}</b></span>}{reportShowsOut&&<span>{reportOutLabel}: <b>{money(u.expense)}</b></span>}{reportKind==="todos"&&<span>Saldo: <b>{money(u.balance)}</b></span>}</div>)}</div></div>}
