 {reportByCategory.length>0&&<div className="mg-report-section mg-report-categories"><h3>Resumo por categoria</h3><div className="mg-table-wrap"><table><thead><tr><th>Categoria</th>{reportShowsIn&&<th>Entradas</th>}{reportShowsOut&&<th>{reportKind==="todos"?"Saídas / despesas":reportOutLabel}</th>}</tr></thead><tbody>{reportByCategory.map(([category,v])=><tr key={category}><td>{category}</td>{reportShowsIn&&<td className="mg-positive">{money(v.in)}</td>}{reportShowsOut&&<td className="mg-negative">{money(v.out)}</td>}</tr>)}</tbody><tfoot><tr><th>Total</th>{reportShowsIn&&<th>{money(reportIncoming)}</th>}{reportShowsOut&&<th>{money(reportOutgoing)}</th>}</tr></tfoot></table></div></div>}
 <div className="mg-report-totals"><strong>Totais do período</strong>{reportShowsIn&&<span>Entradas: <b>{money(reportIncoming)}</b></span>}{reportShowsOut&&<span>{reportKind==="todos"?"Saídas / despesas":reportOutLabel}: <b>{money(reportOutgoing)}</b></span>}{reportKind==="todos"&&<span className="mg-report-final-result">Saldo final: <b>{money(reportIncoming-reportOutgoing)}</b></span>}</div>
